-- Source: sql/analysis/10_analytical_views.sql
{{ config(materialized='view') }}

SELECT
  c.segment_type,
  c.segment_name,
  c.retail_year,
  c.period,
  c.net_revenue AS net_revenue_cy,
  p.net_revenue AS net_revenue_py,
  c.net_revenue - p.net_revenue AS net_revenue_change,
  100.0 * (
    CAST(c.net_revenue AS DOUBLE) / NULLIF(CAST(p.net_revenue AS DOUBLE), 0) - 1
  ) AS net_revenue_yoy_pct,
  c.sales_revenue AS sales_revenue_cy,
  p.sales_revenue AS sales_revenue_py,
  100.0 * (
    CAST(c.sales_revenue AS DOUBLE) / NULLIF(CAST(p.sales_revenue AS DOUBLE), 0) - 1
  ) AS sales_revenue_yoy_pct,
  c.returns_value AS returns_value_cy,
  p.returns_value AS returns_value_py,
  c.transactions AS transactions_cy,
  p.transactions AS transactions_py,
  100.0 * (
    CAST(c.transactions AS DOUBLE) / NULLIF(CAST(p.transactions AS DOUBLE), 0) - 1
  ) AS transactions_yoy_pct,
  c.aov AS aov_cy,
  p.aov AS aov_py,
  c.upt AS upt_cy,
  p.upt AS upt_py,
  c.asp AS asp_cy,
  p.asp AS asp_py,
  c.gross_margin AS gross_margin_cy,
  p.gross_margin AS gross_margin_py,
  c.gross_margin_pct AS gross_margin_pct_cy,
  p.gross_margin_pct AS gross_margin_pct_py
FROM {{ ref('v_kpi_segment_period') }} AS c
JOIN {{ ref('v_kpi_segment_period') }} AS p
  ON p.segment_type = c.segment_type
  AND p.segment_name = c.segment_name
  AND p.period = c.period
  AND p.retail_year = c.retail_year - 1
